#[cfg(unix)]
fn generate_key_file(path: &OsStr) -> std::io::Result<()> {
    // Use the raw OS bytes so a path containing non-UTF-8 bytes refers to
    // exactly the name the user passed, with no lossy substitution.
    let c_path = CString::new(path.as_bytes()).map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "target path contains a NUL byte",
        )
    })?;

    // This stack array is the only buffer this command directly holdsolds
    // that contains the generated key material: getrandom draws straight
    // into it (the crate forwards the buffer to the getrandom(2) syscall
    // without copying it) and the save code only ever borrows it. Whatever
    // happens below -- success, a random-source failure after zero, some,
    // or all 32 bytes, or a failure creating/permissioning/writing/closing
    // the file -- the array is wiped before this operation returns, and the
    // wipe must survive an optimizing compiler. It therefore lives here in
    // this wrapper rather than at the individual return sites, so no error
    // branch inside the save logic can bypass it.
    let mut key = [0u8; KEY_LEN];
    let outcome = save_key_file(&c_path, path, &mut key);
    secure_zero(&mut key);
    outcome
}

#[cfg(unix)]
fn save_key_file(
    c_path: &CString,
    path: &OsStr,
    key: &mut [u8; KEY_LEN],
) -> std::io::Result<()> {
    // Draw the key from the OS CSPRNG first. If the random source is
    // unavailable nothing is ever created at the target path. The bytes
    // already delivered on a mid-draw failure are secret material even
    // though no complete key exists; they are wiped by the caller and are
    // never zero-padded into a stand-in key or reported anywhere.
    if let Err(e) = getrandom::fill(key) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            format!("cryptographic random source unavailable: {e}"),
        ));
    }

    // O_CREAT | O_EXCL: fail if anything already exists at the path (file,
    // directory, or symlink -- including a dangling one, which O_NOFOLLOW
    // also rejects), so a pre-existing object is never overwritten or
    // followed. mode 0600 contains no group/other bits, and the umask can
    // only strip bits, never add them: group/other therefore never gain
    // access, not even for an instant. A strict umask (e.g. 0777) can also
    // strip the owner bits, leaving 0000; that is repaired with fchmod and
    // verified before any key byte is written (see ensure_owner_only_mode).
    let fd = unsafe {
        libc::open(
            c_path.as_ptr(),
            libc::O_WRONLY
                | libc::O_CREAT
                | libc::O_EXCL
                | libc::O_NOFOLLOW
                | libc::O_CLOEXEC,
            0o600,
        )
    };
    if fd < 0 {
        let e = std::io::Error::last_os_error();
        return Err(std::io::Error::new(
            e.kind(),
            format!("cannot create key file {}: {e}", render_path(path)),
        ));
    }
    let fd = fd as RawFd;

    // Enforce and confirm exactly 0600 before writing, then write and fsync.
    // On any failure the inode we just created is unlinked by abort_save; an
    // object predating this invocation is never touched. The key buffer
    // itself is wiped by generate_key_file on the way out of every arm below
    // (including the close-failure arm), so it is not zeroed here.
    let outcome = ensure_owner_only_mode(fd).and_then(|()| write_key(fd, key));

